// The only place to configure this workflow.
const TELEGRAM_CHAT_ID = '';  // put your Telegram chat ID here   // CRM manager's Telegram chat ID. Empty = the run waits as pending_approval.
const HOLDOUT_PCT = 10;        // random control group, so the lift can be measured
const COOLDOWN_DAYS = 90;      // never contact the same buyer twice inside this window
const j = $input.first().json;
const fromWebhook = !!j.headers;
const asked = (j.body && j.body.source) || '';
return [{ json: {
  source: fromWebhook ? (['dashboard', 'manual'].includes(asked) ? asked : 'api') : 'schedule',
  from_webhook: fromWebhook,
  chat_id: String(TELEGRAM_CHAT_ID).trim(),
  holdout_pct: HOLDOUT_PCT, cooldown_days: COOLDOWN_DAYS
} }];

// One message per favourite-category group (not per customer): 1 LLM call, about 1k tokens.
const run = $input.first().json;
const AR = {
  'Men boxers': 'البوكسرات الرجالي', 'Men tops': 'التيشيرتات الرجالي', 'Men underwear': 'الملابس الداخلية الرجالي',
  'Men bottoms': 'البناطيل الرجالي', 'Women pajamas': 'البيجامات الحريمي', 'Women tops': 'البلوزات الحريمي',
  'Women bras': 'الصدريات الحريمي', 'Women underwear': 'الملابس الداخلية الحريمي', 'Women bottoms': 'البناطيل الحريمي',
  'Girls pajamas': 'البيجامات البناتي', 'Boys pajamas': 'البيجامات الولادي', 'Girls underwear': 'الملابس الداخلية البناتي',
  'Kids underwear': 'الملابس الداخلية للأطفال', 'Socks': 'الشرابات', 'Home textiles': 'مفروشات البيت', 'Accessories': 'الإكسسوارات'
};
const groups = (run.groups || []).map(g => ({ category: g.category, category_ar: AR[g.category] || g.category, customers: g.customers }));
const system = [
  'You write short re-engagement messages for Cottonil, an Egyptian underwear and homewear brand, in Egyptian Arabic.',
  'Write ONE message per category in the list. Each message:',
  '- starts with {{first_name}} (the CRM fills it in), 110-220 characters;',
  '- mentions the category naturally using its Arabic name;',
  '- is warm and short, not pushy; at most one emoji;',
  '- contains NO discount, price, percentage, number, date, free item or promise (do not claim a new collection);',
  '- ends by inviting them to visit the nearest branch or the website.',
  'Return JSON only: {"messages":[{"category":"<English category exactly as given>","text":"..."}]}'
].join('\n');
return [{ json: {
  run, groups, ar: AR,
  request_body: {
    model: 'openai/gpt-4.1-mini', temperature: 0.4, response_format: { type: 'json_object' },
    messages: [{ role: 'system', content: system }, { role: 'user', content: JSON.stringify(groups) }]
  }
} }];

// Guardrail on generated text: a message with a number, a discount word or no {{first_name}} is replaced
// by a safe template. The brand never promises something the business did not approve.
const b = $('Prepare message brief').first().json;
const run = b.run;
let llm = [];
try { llm = JSON.parse($input.first().json.choices[0].message.content).messages || []; } catch (e) { llm = []; }
const BANNED = /[0-9\u0660-\u0669%]|خصم|تخفيض|عرض|مجان|ببلاش|كوبون/;
const ok = t => typeof t === 'string' && t.includes('{{first_name}}') && t.length >= 60 && t.length <= 300
  && /[\u0600-\u06FF]/.test(t) && !BANNED.test(t.replace('{{first_name}}', ''));
const template = g => '{{first_name}}، وحشتنا في كوتونيل! ' + g.category_ar + ' اللي بتحبها مستنياك في أقرب فرع أو على الموقع.';
let fromLlm = 0;
const messages = b.groups.map(g => {
  const m = llm.find(x => x && x.category === g.category);
  if (m && ok(m.text)) { fromLlm++; return { category: g.category, customers: g.customers, text: m.text.trim(), source: 'llm' }; }
  return { category: g.category, customers: g.customers, text: template(g), source: 'template' };
});
const nf = n => Number(n || 0).toLocaleString('en-US');
const top = messages.slice(0, 3).map(m => m.category + ' (' + nf(m.customers) + ')').join(', ');
const summary = 'Run #' + run.run_id + ': ' + nf(run.selected) + ' high-value buyers dormant for over a year (' + nf(run.past_spend_egp)
  + ' EGP past spend). ' + nf(run.treatment) + ' to contact, ' + nf(run.holdout) + ' held out to measure the lift. Top groups: ' + top
  + '. ' + messages.length + ' messages (' + fromLlm + ' AI-written, ' + (messages.length - fromLlm) + ' template). Waiting for CRM approval.';
return [{ json: {
  run, messages, summary, llm_messages: fromLlm,
  response: { status: 'pending_approval', summary, run_id: run.run_id, selected: run.selected, treatment: run.treatment,
              holdout: run.holdout, past_spend_egp: run.past_spend_egp, groups: messages.length,
              sample_message: messages[0] ? messages[0].text : '' }
} }];

const r = $input.first().json;
const summary = 'Run #' + r.run_id + ': no high-value dormant buyer is outside the ' + $('Config').first().json.cooldown_days + '-day cooldown. Nothing to send.';
return [{ json: { response: { status: 'nothing_to_do', summary, run_id: r.run_id } } }];
